                            /** Format: date-time */
                            createdAt: string;
                            /** Format: date-time */
                            editedAt: string | null;
                            /** Format: date-time */
                            deletedAt: string | null;
                            /** @description Who deleted it for everyone: the sender, or the other person in a direct chat */
