                                    /** @enum {string} */
                                    game: "fanorona" | "ludo" | "eights" | "words" | "dots" | "memory" | "reflex" | "market" | "snack";
                                    /** @enum {string} */
                                    result: "won" | "lost" | "draw";
                                    /** @description Your score, then the bot's best, in the games that keep one: boxes, pairs or word points */
                                    score?: number[];
