                                    userId: string;
                                    move: {
                                        /** @enum {string} */
                                        hand: "rock" | "paper" | "scissors";
                                    } | {
                                        pick: number;
                                        seed: number;
                                    } | {
                                        n: number;
                                    } | {
                                        shots: ("left" | "middle" | "right")[];
                                        dives: ("left" | "middle" | "right")[];
                                    } | {
                                        letter: string;
                                    } | {
                                        choice: number;
                                    } | {
                                        sealed: string;
                                    } | {
                                        shot: number;
                                    } | {
                                        cell: number;
                                    } | {
                                        col: number;
                                    };
